#!/usr/bin/env bash
# Remove files generated by demos, scans and tests. Only touches paths inside this project.
set -eu
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"
for path in demo-output reposcan-output walkthrough-output .pytest_cache .mypy_cache .ruff_cache .coverage coverage.xml htmlcov build dist; do
  [ -e "$path" ] && rm -rf -- "./$path" && echo "removed $path"
done
find . -path ./.venv -prune -o -type d -name __pycache__ -print0 | xargs -0 -r rm -rf --
echo "clean (the virtual environment .venv was left in place)"
